    self.pair_energy: Dict[Tuple[str, str], float] = {}
    self.pair_waypoints: Dict[Tuple[str, str], List[Tuple[float, float]]] = {}

def sync_nodes(
    self,
    base_xy: Tuple[float, float],
    targets: Dict[str, Dict[str, Any]],
    slip_base: Dict[str, float],
    force_rebuild: bool = False,
) -> None:
    # Rebuild graph if empty or if slip_base drifted meaningfully (> 0.035)
    need_rebuild = force_rebuild or not self.pf.adj
    if not need_rebuild:
        for k, v in slip_base.items():
            if abs(v - self.pf.last_slip_built.get(k, -1.0)) > 0.035:
                need_rebuild = True
                break
    if need_rebuild:
        self.pf.build_graph(slip_base)
        self.dijkstra_trees.clear()
        self.pair_ticks.clear()
        self.pair_energy.clear()
        self.pair_waypoints.clear()

    self.node_coords["BASE"] = base_xy
    for tid, tg in targets.items():
        self.node_coords[tid] = (float(tg["x"]), float(tg["y"]))

    # Ensure every permanent node has a Dijkstra tree and pairwise entries
    all_ids = ["BASE"] + list(targets.keys())
    new_ids = [nid for nid in all_ids if nid not in self.dijkstra_trees]
    if not new_ids:
        return

    for nid in new_ids:
        nx, ny = self.node_coords[nid]
        _, parent = self.pf.single_source_dijkstra(nx, ny)
        self.dijkstra_trees[nid] = parent

    for u in all_ids:
        ux, uy = self.node_coords[u]
        par = self.dijkstra_trees[u]
        for v in all_ids:
            if u == v or (u, v) in self.pair_ticks:
                continue
            vx, vy = self.node_coords[v]
            wps, tks, eng = self.pf.extract_and_smooth(ux, uy, vx, vy, par, slip_base)
            self.pair_ticks[(u, v)] = tks
            self.pair_energy[(u, v)] = eng
            self.pair_waypoints[(u, v)] = wps

def compute_from_rover(
    self, rx: float, ry: float, dest_ids: Sequence[str], slip_base: Dict[str, float]
) -> Tuple[Dict[str, float], Dict[str, float], Dict[str, List[Tuple[float, float]]]]:
    _, par = self.pf.single_source_dijkstra(rx, ry)
    r_ticks: Dict[str, float] = {}
    r_energy: Dict[str, float] = {}
    r_wps: Dict[str, List[Tuple[float, float]]] = {}
    for v in dest_ids:
        vx, vy = self.node_coords[v]
        # Check if rover is already inside sampling radius of target!
        d_euclid = math.hypot(vx - rx, vy - ry)
        if v != "BASE" and d_euclid <= 1.50:
            r_ticks[v] = 0.0
            r_energy[v] = 0.0
            r_wps[v] = [(rx, ry), (vx, vy)]
        else:
            wps, tks, eng = self.pf.extract_and_smooth(rx, ry, vx, vy, par, slip_base)
            r_ticks[v] = tks
            r_energy[v] = eng
            r_wps[v] = wps
    return r_ticks, r_energy, r_wps

