        return []
    while time.perf_counter() < deadline_s:
        best_cand = None
        best_pos = -1
        best_ratio = -1e18
        best_ev = None
        for tid in tids:
            if tid in used:
                continue
            positions = [len(seq)]
            if len(seq) <= 14:
                positions = list(range(len(seq) + 1))
            else:
                positions = list(range(0, len(seq) + 1, 3)) + [len(seq)]
