def greedy_fill(seed_seq: List[str], urgency_w: float = 0.0, energy_w: float = 0.35, deadline_s: float = 1e18) -> List[str]:
    seq = list(seed_seq)
    used = set(seq)
    cur_ev = eval_seq(seq)
    if cur_ev is None:
        return []
    while time.perf_counter() < deadline_s:
        best_cand = None
        best_pos = -1
        best_ratio = -1e18
        best_ev = None
        for tid in tids:
            if tid in used:
                continue
            positions = [len(seq)]
            if len(seq) <= 14:
                positions = list(range(len(seq) + 1))
            else:
                positions = list(range(0, len(seq) + 1, 3)) + [len(seq)]
            for pos in positions:
                cand_seq = seq[:pos] + [tid] + seq[pos:]
                ev = eval_seq(cand_seq)
                if ev is None:
                    continue
                d_util = ev[0] - cur_ev[0]
                if d_util <= 0.05:
                    continue
                dt_cost = max(1.0, float(ev[2] - cur_ev[2]))
                de_net = max(0.0, cur_ev[3] - ev[3])
                comb_cost = max(1.5, dt_cost + energy_w * de_net)
                ratio = d_util / (comb_cost ** 0.88)
                dl = avail_targets[tid]["deadline_tick"]
                if urgency_w > 0.0 and dl is not None and dl > start_tick:
                    ratio *= 1.0 + urgency_w * max(0.0, 1.0 - (dl - start_tick) / 250.0)
