        used.add(best_cand)
        cur_ev = best_ev
    return seq

def local_improve(
    seq: List[str], deadline_s: float
) -> Tuple[List[str], Tuple[float, float, int, float]]:
    ev = eval_seq(seq)
    if ev is None:
        return [], (0.0, 0.0, start_tick, start_bat)
