                cev = eval_seq(cand)
                if cev is not None and cev[0] > ev[0] + 1e-4:
                    seq, ev = cand, cev
                    improved = True
                    break
            if improved:
                break
        if improved:
            continue

        # 2. Relocate single target (Or-opt-1)
        for i in range(n):
            if time.perf_counter() >= deadline_s:
                break
            item = seq[i]
            rem = seq[:i] + seq[i + 1:]
            for j in range(n):
                if j == i:
                    continue
                cand = rem[:j] + [item] + rem[j:]
                cev = eval_seq(cand)
                if cev is not None and cev[0] > ev[0] + 1e-4:
                    seq, ev = cand, cev
                    improved = True
                    break
            if improved:
                break
        if improved:
            continue

