            if time.perf_counter() >= deadline_s:
                break
            for pos in range(len(seq) + 1):
                cand = seq[:pos] + [tid] + seq[pos:]
                cev = eval_seq(cand)
                if cev is not None and cev[0] > ev[0] + 1e-3:
                    seq, ev = cand, cev
                    improved = True
                    break
            if improved:
                break
        if improved:
            continue

        # 4. 1-for-1 Swap: replace a lower-value target in seq with a higher-value unused target!
        unused_sorted = sorted(
            (u for u in tids if u not in used),
            key=lambda u: -avail_targets[u]["value"],
        )
        for i in range(n):
            if time.perf_counter() >= deadline_s:
                break
            v_cur = avail_targets[seq[i]]["value"]
            rem = seq[:i] + seq[i + 1:]
            for cand_u in unused_sorted:
                if avail_targets[cand_u]["value"] < v_cur:
                    # Still allow equal value if much cheaper/better utility, skip strictly lower unless space opens
                    if avail_targets[cand_u]["value"] < v_cur - 0.5:
                        break
                # Try inserting cand_u at i and best neighbor positions
                for pos in (i, max(0, i - 1), min(len(rem), i + 1), len(rem)):
                    cand = rem[:pos] + [cand_u] + rem[pos:]
                    cev = eval_seq(cand)
                    if cev is not None and cev[0] > ev[0] + 0.05:
                        seq, ev = cand, cev
                        improved = True
                        break
                if improved:
                    break
            if improved:
                break
    return seq, ev

